import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_admin_token(token):
    """Verify HMAC-based admin token"""
    if not token:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    payload, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department - internal admin tool"""
    auth = request.headers.get('X-Admin-Token', '')
    if not verify_admin_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    include_email = request.args.get('include_email', 'false')

    # Build query based on requested fields
    if include_email.lower() == 'true':
        fields = 'username, email, department, role'
    else:
        fields = 'username, department, role'

    # Filter by department
    query = f"SELECT {fields} FROM users WHERE department = '{department}'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('search', f'dept:{department}', auth[:16] if auth else 'unknown')
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID"""
    auth = request.headers.get('X-Admin-Token', '')
    if not verify_admin_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute(
        'SELECT id, username, email, department, role FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
